    chat_id: chatId
  }
};

/**
 * n8n HTML TEMPLATE INJECTOR
 * Corporate blue-and-white report design
 *
 * Input:  $json.output (Markdown string from AI Agent)
 * Output: $json.html (complete HTML document for PDF conversion)
 *
 * No external JavaScript packages required.
 */

const item = $input.item.json;

const markdown = item.output;

if (typeof markdown !== "string" || !markdown.trim()) {
  throw new Error(
    "HTML Template Injector: The incoming 'output' field is missing or empty."
  );
}

// --------------------------------------------------
// 1. HTML ESCAPING
// --------------------------------------------------

function escapeHtml(value = "") {
  return String(value)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

// --------------------------------------------------
// 2. EXTRACT DOCUMENT METADATA FROM MARKDOWN
// --------------------------------------------------

const firstHeading = markdown.match(/^#\s+(.+)$/m);

const reportTitle = firstHeading
  ? firstHeading[1].trim()
  : "Industry Report";

function extractMetadata(label, fallback = "") {
  const pattern = new RegExp(
    "^\\*\\*" + label + "\\s*:\\*\\*\\s*(.+?)\\s*$",
    "mi"
  );

  const match = markdown.match(pattern);
  return match ? match[1].trim() : fallback;
}

const subject = extractMetadata("Subject", "Industry Report");
const targetGoal = extractMetadata("Target Goal", "");
const reportDate = extractMetadata("Date", "");

const companyName = item.companyName || "INDUSTRY REPORT";
const website = item.website || "";
const author = item.author || "";

// Escape metadata before placing it into HTML.
const safeTitle = escapeHtml(reportTitle);
const safeSubject = escapeHtml(subject);
const safeGoal = escapeHtml(targetGoal);
const safeDate = escapeHtml(reportDate);
const safeCompany = escapeHtml(companyName);
const safeWebsite = escapeHtml(website);
const safeAuthor = escapeHtml(author);

// --------------------------------------------------
// 3. MARKDOWN INLINE FORMATTING
// --------------------------------------------------

function inlineMarkdown(text = "") {
  // Escape all incoming content before adding HTML tags.
  let html = escapeHtml(text);

  // Inline code.
  html = html.replace(
    /`([^`]+)`/g,
    "<code>$1</code>"
  );

  // Bold and italic.
  html = html.replace(
    /\*\*\*(.+?)\*\*\*/g,
    "<strong><em>$1</em></strong>"
  );

  html = html.replace(
    /\*\*(.+?)\*\*/g,
    "<strong>$1</strong>"
  );

  html = html.replace(
    /__(.+?)__/g,
    "<strong>$1</strong>"
  );

  html = html.replace(
    /(^|[^*])\*([^*\n]+)\*(?!\*)/g,
    "$1<em>$2</em>"
  );

  html = html.replace(
    /(^|[^_])_([^_\n]+)_(?!_)/g,
    "$1<em>$2</em>"
  );

  // Basic Markdown links.
  html = html.replace(
    /\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)/g,
    '<a href="$2">$1</a>'
  );

  return html;
}

// --------------------------------------------------
// 4. CONVERT MARKDOWN BLOCKS INTO HTML
// --------------------------------------------------

function markdownToHtml(source) {
  const lines = source.replace(/\r\n?/g, "\n").split("\n");

  const output = [];

  let paragraph = [];
  let listType = null;
  let listItems = [];

  function flushParagraph() {
    if (paragraph.length) {
      output.push(
        `<p>${inlineMarkdown(paragraph.join(" "))}</p>`
      );
      paragraph = [];
    }
  }

  function flushList() {
    if (!listType) return;

    const tag = listType === "ol" ? "ol" : "ul";

    output.push(
      `<${tag}>${listItems.map(entry =>
        `<li>${inlineMarkdown(entry)}</li>`
      ).join("")}</${tag}>`
    );

    listType = null;
    listItems = [];
  }

  function flushAll() {
    flushParagraph();
    flushList();
  }

  for (const rawLine of lines) {
    const line = rawLine.trim();

    // Blank line.
    if (!line) {
      flushAll();
      continue;
    }

    // Horizontal rule.
    if (/^(---+|___+|\*\s*\*\s*\*+)$/.test(line)) {
      flushAll();
      output.push('<hr class="section-rule">');
      continue;
    }

    // Headings.
    const heading = line.match(/^(#{1,6})\s+(.+)$/);

    if (heading) {
      flushAll();

      const level = heading[1].length;
      const text = inlineMarkdown(heading[2]);

      output.push(
        `<h${level}>${text}</h${level}>`
      );
      continue;
    }

    // Unordered list.
    const bullet = line.match(/^[-*+]\s+(.+)$/);

    if (bullet) {
      flushParagraph();

      if (listType !== "ul") {
        flushList();
        listType = "ul";
      }

      listItems.push(bullet[1]);
      continue;
    }

    // Ordered list.
    const numbered = line.match(/^\d+[.)]\s+(.+)$/);

    if (numbered) {
      flushParagraph();

      if (listType !== "ol") {
        flushList();
        listType = "ol";
      }

      listItems.push(numbered[1]);
      continue;
    }

    // Normal paragraph.
    flushList();
    paragraph.push(line);
  }

  flushAll();

  return output.join("\n");
}

// --------------------------------------------------
// 5. SEPARATE COVER METADATA FROM REPORT BODY
// --------------------------------------------------

// Remove the first H1 title, metadata lines, and initial
// horizontal rule from the interior report content.

let bodyMarkdown = markdown
  .replace(/^#\s+.+\n?/, "")
  .replace(/^\*\*(Subject|Target Goal|Date)\s*:\*\*.*(?:\n|$)/gim, "")
  .replace(/^\s*---+\s*$/gm, "");

const bodyHtml = markdownToHtml(bodyMarkdown);

// --------------------------------------------------
// 6. BUILD CORPORATE PDF HTML TEMPLATE
// --------------------------------------------------

const html = `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">

<title>${safeTitle}</title>

<style>
  :root {
    --blue: #159bd0;
    --blue-dark: #0877a7;
    --blue-deep: #075b87;
    --blue-light: #eaf7fc;
    --text: #414b54;
    --muted: #78848d;
    --border: #c8e8f4;
  }

  * {
    box-sizing: border-box;
  }

  html {
    -webkit-print-color-adjust: exact;
    print-color-adjust: exact;
  }

  body {
    margin: 0;
    font-family: Arial, Helvetica, sans-serif;
    color: var(--text);
    font-size: 10pt;
    line-height: 1.65;
    background: #fff;
  }

  /* COVER PAGE */

  .cover {
    position: relative;
    height: 297mm;
    overflow: hidden;
    page-break-after: always;
    background: #fff;
  }

  .cover-header {
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    height: 37mm;
    padding: 12mm 17mm 7mm;
    display: flex;
    justify-content: space-between;
    align-items: center;
    border-bottom: 2px solid var(--border);
    z-index: 3;
    background: #fff;
  }

  .brand {
    font-weight: 700;
    font-size: 16pt;
    color: var(--blue-dark);
    letter-spacing: .6px;
    text-transform: uppercase;
  }

  .cover-label {
    font-size: 8pt;
    font-weight: 700;
    color: var(--blue-dark);
    letter-spacing: 1.4px;
    text-align: right;
  }

  .cover-shape {
    position: absolute;
    top: 37mm;
    left: 0;
    right: 0;
    bottom: 0;
    background: linear-gradient(
      140deg,
      #31b6e5 0%,
      #159bd0 48%,
      #0876ac 100%
    );
    clip-path: polygon(
      0 0,
      100% 0,
      100% 88%,
      76% 100%,
      0 100%
    );
  }

  .cover-content {
    position: absolute;
    top: 86mm;
    left: 17mm;
    right: 17mm;
    color: white;
    z-index: 2;
  }

  .cover-kicker {
    margin-bottom: 7mm;
    font-size: 9pt;
    font-weight: 700;
    letter-spacing: 2px;
    text-transform: uppercase;
  }

  .cover h1 {
    max-width: 165mm;
    margin: 0 0 8mm;
    font-size: 32pt;
    font-weight: 700;
    line-height: 1.17;
    letter-spacing: -.5px;
    overflow-wrap: anywhere;
  }

  .cover-subject {
    max-width: 150mm;
    font-size: 14pt;
    line-height: 1.5;
  }

  .cover-goal {
    margin-top: 9mm;
    padding-top: 5mm;
    border-top: 1px solid rgba(255,255,255,.65);
    font-size: 10pt;
    font-weight: 600;
  }

  .cover-meta {
    margin-top: 5mm;
    font-size: 9pt;
  }

  .cover-footer {
    position: absolute;
    left: 17mm;
    right: 17mm;
    bottom: 11mm;
    z-index: 3;
    color: white;
    font-size: 8.5pt;
    display: flex;
    justify-content: space-between;
    gap: 8mm;
  }

  /* INTERIOR PAGES */

  .report-header {
    padding: 0 0 4mm;
    margin-bottom: 9mm;
    border-bottom: 2px solid var(--blue);
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 8mm;
  }

  .report-brand {
    color: var(--blue-dark);
    font-size: 9pt;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: .5px;
  }

  .report-label {
    font-size: 8pt;
    color: var(--muted);
    text-align: right;
  }

  .report-content {
    overflow-wrap: break-word;
  }

  h2 {
    margin: 9mm 0 4mm;
    padding-bottom: 2.5mm;
    color: var(--blue-dark);
    font-size: 17pt;
    line-height: 1.3;
    font-weight: 600;
    border-bottom: 1px solid var(--border);
    break-after: avoid;
    page-break-after: avoid;
  }

  h3 {
    margin: 6mm 0 2.5mm;
    color: var(--blue-dark);
    font-size: 12pt;
    line-height: 1.4;
    break-after: avoid;
    page-break-after: avoid;
  }

  h4, h5, h6 {
    color: var(--blue-dark);
    break-after: avoid;
    page-break-after: avoid;
  }

  p {
    margin: 0 0 4mm;
    orphans: 3;
    widows: 3;
  }

  strong {
    color: #273b47;
  }

  em {
    color: #4e6471;
  }

  ul, ol {
    margin: 2mm 0 5mm;
    padding-left: 7mm;
  }

  li {
    margin-bottom: 2.5mm;
    padding-left: 1mm;
  }

  li::marker {
    color: var(--blue);
    font-weight: 700;
  }

  a {
    color: var(--blue-dark);
    text-decoration: none;
  }

  code {
    font-family: Consolas, monospace;
    font-size: 9pt;
    background: var(--blue-light);
    padding: 1px 3px;
    border-radius: 2px;
  }

  .section-rule {
    border: 0;
    border-top: 1px solid var(--border);
    margin: 6mm 0;
  }

  blockquote {
    margin: 5mm 0;
    padding: 4mm 5mm;
    border-left: 3px solid var(--blue);
    background: var(--blue-light);
  }

  .report-footer {
    margin-top: 12mm;
    padding-top: 3mm;
    border-top: 1px solid var(--border);
    color: var(--muted);
    font-size: 8pt;
    display: flex;
    justify-content: space-between;
    gap: 6mm;
  }

  @page {
    size: A4;
    margin: 16mm 17mm 17mm;
  }

  @page:first {
    size: A4;
    margin: 0;
  }

  @media print {
    body {
      background: white;
      -webkit-print-color-adjust: exact;
      print-color-adjust: exact;
    }

    .cover {
      height: 297mm;
      page-break-after: always;
      break-after: page;
    }

    .report-content img {
      max-width: 100%;
      height: auto;
    }
  }
</style>
</head>

<body>

  <!-- DESIGNED COVER PAGE -->
  <section class="cover">

    <header class="cover-header">
      <div class="brand">${safeCompany}</div>
      <div class="cover-label">
        INDUSTRY REPORT<br>
        RESEARCH &amp; ANALYSIS
      </div>
    </header>

    <div class="cover-shape"></div>

    <div class="cover-content">
      <div class="cover-kicker">Industry Report</div>

      <h1>${safeTitle}</h1>

      <div class="cover-subject">
        ${safeSubject}
      </div>

      ${safeGoal ? `
        <div class="cover-goal">
          Target Goal: ${safeGoal}
        </div>
      ` : ""}

      <div class="cover-meta">
        ${safeDate ? `<div>${safeDate}</div>` : ""}
        ${safeAuthor ? `<div>Prepared by: ${safeAuthor}</div>` : ""}
      </div>
    </div>

    <footer class="cover-footer">
      <span>${safeCompany}</span>
      <span>${safeWebsite}</span>
    </footer>

  </section>

  <!-- INTERIOR REPORT -->
  <main>

    <header class="report-header">
      <div class="report-brand">${safeCompany}</div>
      <div class="report-label">${safeTitle}</div>
    </header>

    <article class="report-content">
      ${bodyHtml}
    </article>

    <footer class="report-footer">
      <span>${safeCompany}</span>
      <span>${safeDate}</span>
    </footer>

  </main>

</body>
</html>`;

// --------------------------------------------------
// 7. RETURN DATA TO THE NEXT N8N NODE
// --------------------------------------------------

return {
  json: {
    ...item,
    html,
    reportTitle,
    reportDate,
    pdfTemplate: "corporate-blue-white"
  }
};

